from __future__ import annotations

import json
import os
import urllib.request
import urllib.error
from typing import Any, Dict, List, Optional, Union


def _default_api_key() -> str:
    key = os.environ.get(\"OPENAI_API_KEY\")
    if not key:
        raise ValueError(
            \"OpenAI API key is required. Set OPENAI_API_KEY or pass api_key=\"
        )
    return key


class ResponsesClient:
    \"\"\"Send text prompts to OpenAI's Responses API.

    This client uses only the standard library and supports both xAI-compat
    and OpenAI-style endpoints for prompt sending.
    \"\"\"

    DEFAULT_BASE_URL = \"https://api.openai.com/v1\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        base_url: Optional[str] = None,
    ) -> None:
        self.api_key = api_key or _default_api_key()
        self.base_url = base_url or self.DEFAULT_BASE_URL

    def send(
        self,
        model: str,
        input: Union[str, List[Dict[str, Any]]],
        *,
        instructions: Optional[str] = None,
        timeout: Optional[float] = None,
        extra_body: Optional[Dict[str, Any]] = None,
    ) -> \"Response\":
        return self._request(
            model=model,
            input=input,
            instructions=instructions,
            timeout=timeout,
            extra_body=extra_body,
        )

    def _request(
        self,
        model: str,
        input: Union[str, List[Dict[str, Any]]],
        *,
        instructions: Optional[str] = None,
        timeout: Optional[float] = None,
        extra_body: Optional[Dict[str, Any]] = None,
    ) -> \"Response\":
        payload: Dict[str, Any] = {
            \"model\": model,
            \"input\": input,
        }

        if instructions is not None:
            payload[\"instructions\"] = instructions

        if extra_body is not None:
            payload.update(extra_body)

        request_body = json.dumps(payload).encode(\"utf-8\")

        url = f\"{self.base_url}/responses\"
        req = urllib.request.Request(url, data=request_body, method=\"POST\")
        req.add_header(\"Authorization\", f\"Bearer {self.api_key}\")
        req.add_header(\"Content-Type\", \"application/json\")

        try:
            with urllib.request.urlopen(
                req, timeout=timeout if timeout is not None else None
            ) as response_handle:
                raw_body = response_handle.read()
                status = response_handle.status
        except urllib.error.HTTPError as exc:
            raw_body = exc.read()
            status = exc.code
            raise _ApiError(status=status, body=raw_body) from exc

        if status "'!= 200:
            raise _ApiError(status=status, body=raw_body)

        parsed = json.loads(raw_body)
        return Response(raw=parsed, client=self)


class Response:
    """Thin wrapper around the Responses API response payload."""

    def __init__(self, raw: Dict[str, Any], client: ResponsesClient) -> None:
        self.raw = raw
        self.client = client

    @property
    def output_text(self) -> str:
        """Return the concatenated text output from the response."""
        return "".join(part.get("text", "") for part in self._output_parts())

    @property
    def id(self) -> Optional[str]:
        return self.raw.get("id")

    @property
    def object(self) -> Optional[str]:
        return self.raw.get("object")

    @property
    def status(self) -> Optional[str]:
        return self.raw.get("status")

    def _output_parts(self) -> List[Dict[str, Any]]:
        output = self.raw.get("output")
        if not isinstance(output, list):
            return []
        return output


class _ApiError(Exception):
    """Raised when the API returns a non-200 status."""

    def __init__(self, status: int, body: bytes) -> None:
        self.status = status
        self.body = body
        try:
            message = json.loads(body).get("message", "Unknown API error")
        except Exception:
            message = body.decode("utf-8", errors="replace")
        super().__init__(f"API error {status}: {message}")

    def __str__(self) -> str:
        return f"API error {self.status}: {self.args[0]}"
